WHERE tenant_id=#{tenantId}
AND (campaign_code LIKE CONCAT('%',#{keyword},'%') OR campaign_name LIKE CONCAT('%',#{keyword},'%'))
AND status=#{status}
AND campaign_type=#{campaignType}

mapper.update:
UPDATE crm_campaign SET campaign_name=#{entity.campaignName},campaign_type=#{entity.campaignType},
  starts_at=#{entity.startsAt},ends_at=#{entity.endsAt},status=#{entity.status},version=version+1
WHERE tenant_id=#{tenantId} AND id=#{entity.id} AND version=#{entity.version}

mapper.sql:
WHERE c.tenant_id=#{tenantId}
AND (c.channel_no LIKE CONCAT('%',#{keyword},'%') OR c.name LIKE CONCAT('%',#{keyword},'%'))
AND c.status=#{status}
AND c.channel_type=#{channelType}
AND c.business_owner_user_id=#{businessOwnerUserId}

mapper.select:
SELECT  FROM crm_partner_channel c
LEFT JOIN sys_user u ON u.tenant_id=c.tenant_id AND u.id=c.business_owner_user_id

ORDER BY c.id DESC LIMIT #{size} OFFSET #{offset}

SELECT  FROM crm_partner_channel c
LEFT JOIN sys_user u ON u.tenant_id=c.tenant_id AND u.id=c.business_owner_user_id
WHERE c.tenant_id=#{tenantId} AND c.id=#{id}

SELECT  FROM crm_partner_channel c
LEFT JOIN sys_user u ON u.tenant_id=c.tenant_id AND u.id=c.business_owner_user_id
WHERE c.tenant_id=#{tenantId} AND c.channel_no=#{channelNo}

mapper.update:
UPDATE crm_partner_channel SET name=#{entity.name},channel_type=#{entity.channelType},platform_code=#{entity.platformCode},commission_percent=#{entity.commissionPercent},
  business_owner_user_id=#{entity.businessOwnerUserId},real_name=#{entity.realName},contact_phone_cipher=#{entity.contactPhone},id_card_number_cipher=#{entity.idCardNumber},settlement_method=#{entity.settlementMethod},cooperation_start_date=#{entity.cooperationStartDate},cooperation_end_date=#{entity.cooperationEndDate},payment_account_name_cipher=#{entity.paymentAccountName},payment_account_no_cipher=#{entity.paymentAccountNo},payment_bank_name=#{entity.paymentBankName},status=#{entity.status},remarks=#{entity.remarks},version=version+1
WHERE tenant_id=#{tenantId} AND id=#{entity.id} AND version=#{entity.version}
